TLM.f("Tempora/Pent22-5",{"officium":"Feria Sexta infra Hebdomadam XXII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent22-0","from":{"Introitus":"Tempora/Pent22-0","Oratio":"Tempora/Pent22-0","Lectio":"Tempora/Pent22-0","Graduale":"Tempora/Pent22-0","Evangelium":"Tempora/Pent22-0","Offertorium":"Tempora/Pent22-0","Secreta":"Tempora/Pent22-0","Communio":"Tempora/Pent22-0","Postcommunio":"Tempora/Pent22-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 129:3-4"},{"k":"text","la":"Si iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël."},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi vocem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Si iniquitátes observáveris, Dómine: Dómine, quis sustinébit? quia apud te propitiátio est, Deus Israël."}],"Oratio":[{"k":"text","la":"Deus, refúgium nostrum et virtus: adésto piis Ecclésiæ tuæ précibus, auctor ipse pietátis, et præsta; ut, quod fidéliter pétimus, efficáciter consequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Phil 1:6-11"},{"k":"text","la":"Fratres: Confídimus in Dómino Jesu, quia, qui cœpit in vobis opus bonum, perfíciet usque in diem Christi Jesu. Sicut est mihi justum hoc sentíre pro ómnibus vobis: eo quod hábeam vos in corde, et in vínculis meis, et in defensióne, et confirmatióne Evangélii, sócios gáudii mei omnes vos esse. Testis enim mihi est Deus, quómodo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu: ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi, repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei."}],"Graduale":[{"k":"ref","la":"Ps 132:1-2"},{"k":"text","la":"Ecce, quam bonum et quam jucúndum, habitáre fratres in unum!"},{"k":"text","la":"Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 113:11"},{"k":"text","la":"Qui timent Dóminum sperent in eo: adjútor et protéctor eórum est. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 22:15-21"},{"k":"text","la":"In illo témpore: Abeúntes pharisǽi consílium iniérunt, ut cáperent Jesum in sermóne. Et mittunt ei discípulos suos cum Herodiánis, dicéntes: Magíster, scimus, quia verax es et viam Dei in veritáte doces, et non est tibi cura de áliquo: non enim réspicis persónam hóminum: dic ergo nobis, quid tibi vidétur, licet censum dare Cǽsari, an non? Cógnita autem Jesus nequítia eórum, ait: Quid me tentátis, hypócritæ? Osténdite mihi numísma census. At illi obtulérunt ei denárium. Et ait illis Jesus: Cujus est imágo hæc et superscríptio? Dicunt ei: Cǽsaris. Tunc ait illis: Réddite ergo, quæ sunt Cǽsaris, Cǽsari; et, quæ sunt Dei, Deo."}],"Offertorium":[{"k":"ref","la":"Esth 14:12; 14:13"},{"k":"text","la":"Recordáre mei, Dómine, omni potentátui dóminans: et da sermónem rectum in os meum, ut pláceant verba mea in conspéctu príncipis."}],"Secreta":[{"k":"text","la":"Da, miséricors Deus: ut hæc salutáris oblátio et a própriis nos reátibus indesinénter expédiat, et ab ómnibus tueátur advérsis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 16:6"},{"k":"text","la":"Ego clamávi, quóniam exaudísti me, Deus: inclína aurem tuam et exáudi verba mea."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, sacri dona mystérii, humíliter deprecántes: ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"e53f570590a794b6":{"t":"Ps 129, 3-4, Ps 129, 1-2\n(Ps 129, 3-4) Ako se budeš spominjao prestupaka, Gospodine, Gospodine, tko će opstati? Ali je u tebe smilovanje, Bože Izraelov. (Ps 129, 1-2) Iz dubine vapijem k tebi, Gospodine, Gospodine, usliši moj glas.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 129, 3-4) Ako se budeš spominjao prestupaka, Gospodine, Gospodine, tko će opstati? Ali je u tebe smilovanje, Bože Izraelov."},"18f92b06d8067df8":{"t":"<i>Pomolimo se</i>.\nBože, snago i utočište naše, ti koji si sam početnik dobrote, pokaži se milostiv molitvama svoje Crkve te podaj da uspješno postignemo ono što s pouzdanjem molimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"2a2cc797d636a0b6":{"t":"Fil 1, 6-11\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo, uzdamo se u Gospodina da će onaj, koji je u vama započeo dobro djelo i dovršiti ga do dana Isusa Krista. Pravo je da ovako mislim o svima vama, jer sam duboko uvjeren da ste vi svi sudionici moje radosti, kao što u mojim okovima tako i u obrani i potvrdi evanđelja. Bog mi je svjedok, kako za vama čeznem ljubavlju Isusa Krista. I ovo molim: da vaša ljubav sve više i više obiluje znanjem i osjećanjem da odaberete što je bolje, da budete iskreni i besprijekorni za Kristov dan, puni plodova pravde po Isusu Kristu, na Božju slavu i hvalu.","v":"∅ → in"},"e873e358e574fa3e":{"t":"Ps 132, 1-2\nGle, kako je dobro i ugodno da braća stanuju zajedno! Kao najbolje ulje što teče na bradu Aronovu.\n\nPs 113, 11\n<i>Aleluja</i>, <i>aleluja</i>.\nKoji se boje Gospodina neka se uzdaju u njega. On je njihov pomoćnik i štit. <i>Aleluja</i>."},"9aa3262743892301":{"t":"Mt 22, 15-21\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme farizeji održaše vijeće te se dogovoriše kako bi uhvatili Isusa u riječi. Zato pošalju k njemu svoje učenike s herodovcima, i oni mu postave pitanje: Učitelju znamo da si istinit i da doista naučavaš Božju nauku bez obzira na ikoga, jer ne gledaš tko je tko. Reci nam dakle, što ti misliš: je li dopušteno plaćati caru porez ili nije? Isus shvati njihovu zlobu te im reče: Licemjeri, što me kušate? Pokažite mi porezni novac. Oni mu pruže dinar. Nato ih Isus upita: Čija je ova slika i natpis? Oni mu odgovore: Careva. Tada im reče: Dajte caru carevo, a Bogu Božje!"},"2fcd24931cdcb051":{"t":"Est 14, 12 i 13\nSjeti se mene, Gospodine, koji vladaš svakom vlašću, i daj mi u usta pravi govor da se knezu svide moje riječi."},"8eb99f664a7e7799":{"t":"Podaj, milosrdni Bože, da nas ovaj spasnonosni prinos oslobodi od naših krivica i od svih nesreća brani.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"141f367f72df010b":{"t":"Ps 16, 6\nJa vičem, a ti me čuješ, Bože! Prigni svoje uho k meni i usliši moje riječi."},"33ce546681338107":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, darove svetog otajstva i smjerno te molimo da bude na pomoć našoj slabosti ono što si zapovjedio da činimo tebi na spomen:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
